def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(text):
        if not text or not text.isascii() or not text.isdigit():
            return None

        # Small chunks also support amounts beyond Python's int-string limit.
        value = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if len(parts) != arities.get(verb) or any(p == "" for p in parts):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = parts[1]

        if verb == "open":
            if name in accounts:
                rejected.append(index)
                continue

            history.append(((name, None),))
            accounts[name] = (amount, False)
            continue

        if name not in accounts:
            rejected.append(index)
            continue

        balance, frozen = accounts[name]

        if verb == "deposit":
            history.append(((name, accounts[name]),))
            accounts[name] = (balance + amount, frozen)

        elif verb == "withdraw":
            if frozen or balance < amount:
                rejected.append(index)
                continue

            history.append(((name, accounts[name]),))
            accounts[name] = (balance - amount, frozen)

        elif verb == "transfer":
            destination = parts[2]
            if (
                name == destination
                or destination not in accounts
                or frozen
                or balance < amount
            ):
                rejected.append(index)
                continue

            destination_balance, destination_frozen = accounts[destination]
            history.append((
                (name, accounts[name]),
                (destination, accounts[destination]),
            ))
            accounts[name] = (balance - amount, frozen)
            accounts[destination] = (
                destination_balance + amount,
                destination_frozen,
            )

        elif verb == "freeze":
            if frozen:
                rejected.append(index)
                continue

            history.append(((name, accounts[name]),))
            accounts[name] = (balance, True)

        elif verb == "unfreeze":
            if not frozen:
                rejected.append(index)
                continue

            history.append(((name, accounts[name]),))
            accounts[name] = (balance, False)

    balances = {name: state[0] for name, state in accounts.items()}
    return balances, rejected
